use split_decls_genesis :: ourprelude :: * ; use std :: borrow :: Cow ; use rustc_data_structures :: fx :: FxHashSet ; use rustc_index :: IndexVec ; use rustc_index :: bit_set :: DenseBitSet ; use rustc_middle :: bug ; use rustc_middle :: mir :: visit :: * ; use rustc_middle :: mir :: * ; use rustc_middle :: ty :: TyCtxt ; use rustc_mir_dataflow :: Analysis ; use rustc_mir_dataflow :: impls :: { MaybeStorageDead , always_storage_live_locals } ; use tracing :: { debug , instrument } ; use crate :: ssa :: { SsaLocals , StorageLiveLocals } ; #[doc = " Propagate references using SSA analysis."] #[doc = ""] #[doc = " MIR building may produce a lot of borrow-dereference patterns."] #[doc = ""] #[doc = " This pass aims to transform the following pattern:"] #[doc = "   _1 = &raw? mut? PLACE;"] #[doc = "   _3 = *_1;"] #[doc = "   _4 = &raw? mut? *_1;"] #[doc = ""] #[doc = " Into"] #[doc = "   _1 = &raw? mut? PLACE;"] #[doc = "   _3 = PLACE;"] #[doc = "   _4 = &raw? mut? PLACE;"] #[doc = ""] #[doc = " where `PLACE` is a direct or an indirect place expression."] #[doc = ""] #[doc = " There are 3 properties that need to be upheld for this transformation to be legal:"] #[doc = " - place stability: `PLACE` must refer to the same memory wherever it appears;"] #[doc = " - pointer liveness: we must not introduce dereferences of dangling pointers;"] #[doc = " - `&mut` borrow uniqueness."] #[doc = ""] #[doc = " # Stability"] #[doc = ""] #[doc = " If `PLACE` is an indirect projection, if its of the form `(*LOCAL).PROJECTIONS` where:"] #[doc = " - `LOCAL` is SSA;"] #[doc = " - all projections in `PROJECTIONS` have a stable offset (no dereference and no indexing)."] #[doc = ""] #[doc = " If `PLACE` is a direct projection of a local, we consider it as constant if:"] #[doc = " - the local is always live, or it has a single `StorageLive`;"] #[doc = " - all projections have a stable offset."] #[doc = ""] #[doc = " # Liveness"] #[doc = ""] #[doc = " When performing an instantiation, we must take care not to introduce uses of dangling locals."] #[doc = " To ensure this, we walk the body with the `MaybeStorageDead` dataflow analysis:"] #[doc = " - if we want to replace `*x` by reborrow `*y` and `y` may be dead, we allow replacement and"] #[doc = "   mark storage statements on `y` for removal;"] #[doc = " - if we want to replace `*x` by non-reborrow `y` and `y` must be live, we allow replacement;"] #[doc = " - if we want to replace `*x` by non-reborrow `y` and `y` may be dead, we do not replace."] #[doc = ""] #[doc = " # Uniqueness"] #[doc = ""] #[doc = " For `&mut` borrows, we also need to preserve the uniqueness property:"] #[doc = " we must avoid creating a state where we interleave uses of `*_1` and `_2`."] #[doc = " To do it, we only perform full instantiation of mutable borrows:"] #[doc = " we replace either all or none of the occurrences of `*_1`."] #[doc = ""] #[doc = " Some care has to be taken when `_1` is copied in other locals."] #[doc = "   _1 = &raw? mut? _2;"] #[doc = "   _3 = *_1;"] #[doc = "   _4 = _1"] #[doc = "   _5 = *_4"] #[doc = " In such cases, fully instantiating `_1` means fully instantiating all of the copies."] #[doc = ""] #[doc = " For immutable borrows, we do not need to preserve such uniqueness property,"] #[doc = " so we perform all the possible instantiations without removing the `_1 = &_2` statement."] pub (super) struct ReferencePropagation ; impl < 'tcx > crate :: MirPass < 'tcx > for ReferencePropagation { fn is_enabled (& self , sess : & rustc_session :: Session) -> bool { sess . mir_opt_level () >= 2 } #[instrument (level = "trace" , skip (self , tcx , body))] fn run_pass (& self , tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx >) { debug ! (def_id = ? body . source . def_id ()) ; move_to_copy_pointers (tcx , body) ; while propagate_ssa (tcx , body) { } } fn is_required (& self) -> bool { false } } #[doc = " The SSA analysis done by [`SsaLocals`] treats [`Operand::Move`] as a read, even though in"] #[doc = " general [`Operand::Move`] represents pass-by-pointer where the callee can overwrite the"] #[doc = " pointee (Miri always considers the place deinitialized). CopyProp has a similar trick to"] #[doc = " turn [`Operand::Move`] into [`Operand::Copy`] when required for an optimization, but in this"] #[doc = " pass we just turn all moves of pointers into copies because pointers should be by-value anyway."] fn move_to_copy_pointers < 'tcx > (tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx >) { let mut visitor = MoveToCopyVisitor { tcx , local_decls : & body . local_decls } ; for (bb , data) in body . basic_blocks . as_mut_preserves_cfg () . iter_enumerated_mut () { visitor . visit_basic_block_data (bb , data) ; } struct MoveToCopyVisitor < 'a , 'tcx > { tcx : TyCtxt < 'tcx > , local_decls : & 'a IndexVec < Local , LocalDecl < 'tcx > > , } impl < 'a , 'tcx > MutVisitor < 'tcx > for MoveToCopyVisitor < 'a , 'tcx > { fn tcx (& self) -> TyCtxt < 'tcx > { self . tcx } fn visit_operand (& mut self , operand : & mut Operand < 'tcx > , loc : Location) { if let Operand :: Move (place) = * operand { if place . ty (self . local_decls , self . tcx) . ty . is_any_ptr () { * operand = Operand :: Copy (place) ; } } self . super_operand (operand , loc) ; } } } fn propagate_ssa < 'tcx > (tcx : TyCtxt < 'tcx > , body : & mut Body < 'tcx >) -> bool { let typing_env = body . typing_env (tcx) ; let ssa = SsaLocals :: new (tcx , body , typing_env) ; let mut replacer = compute_replacement (tcx , body , ssa) ; debug ! (? replacer . targets) ; debug ! (? replacer . allowed_replacements) ; debug ! (? replacer . storage_to_remove) ; replacer . visit_body_preserves_cfg (body) ; if replacer . any_replacement { crate :: simplify :: remove_unused_definitions (body) ; } replacer . any_replacement } #[derive (Copy , Clone , Debug , PartialEq , Eq)] enum Value < 'tcx > { #[doc = " Not a pointer, or we can't know."] Unknown , #[doc = " We know the value to be a pointer to this place."] #[doc = " The boolean indicates whether the reference is mutable, subject the uniqueness rule."] Pointer (Place < 'tcx > , bool) , } #[doc = " For each local, save the place corresponding to `*local`."] #[instrument (level = "trace" , skip (tcx , body , ssa))] fn compute_replacement < 'tcx > (tcx : TyCtxt < 'tcx > , body : & Body < 'tcx > , ssa : SsaLocals ,) -> Replacer < 'tcx > { let always_live_locals = always_storage_live_locals (body) ; let storage_live = StorageLiveLocals :: new (body , & always_live_locals) ; let mut maybe_dead = MaybeStorageDead :: new (Cow :: Owned (always_live_locals)) . iterate_to_fixpoint (tcx , body , None) . into_results_cursor (body) ; let mut targets = IndexVec :: from_elem (Value :: Unknown , & body . local_decls) ; let mut storage_to_remove = DenseBitSet :: new_empty (body . local_decls . len ()) ; let fully_replaceable_locals = fully_replaceable_locals (& ssa) ; let is_constant_place = | place : Place < '_ > | { if place . projection . first () == Some (& PlaceElem :: Deref) { ssa . is_ssa (place . local) && place . projection [1 ..] . iter () . all (PlaceElem :: is_stable_offset) } else { storage_live . has_single_storage (place . local) && place . projection [..] . iter () . all (PlaceElem :: is_stable_offset) } } ; let mut can_perform_opt = | target : Place < 'tcx > , loc : Location | { if target . projection . first () == Some (& PlaceElem :: Deref) { storage_to_remove . insert (target . local) ; true } else { maybe_dead . seek_after_primary_effect (loc) ; let maybe_dead = maybe_dead . get () . contains (target . local) ; ! maybe_dead } } ; for (local , rvalue , location) in ssa . assignments (body) { debug ! (? local) ; let Value :: Unknown = targets [local] else { bug ! () } ; let ty = body . local_decls [local] . ty ; if ! ty . is_any_ptr () { debug ! ("not a reference or pointer") ; continue ; } let needs_unique = ty . is_mutable_ptr () ; if needs_unique && ! fully_replaceable_locals . contains (local) { debug ! ("not fully replaceable") ; continue ; } debug ! (? rvalue) ; match rvalue { Rvalue :: Use (Operand :: Copy (place) | Operand :: Move (place)) | Rvalue :: CopyForDeref (place) => { if let Some (rhs) = place . as_local () && ssa . is_ssa (rhs) { let target = targets [rhs] ; if ! needs_unique && matches ! (target , Value :: Pointer (..)) { targets [local] = target ; } else { targets [local] = Value :: Pointer (tcx . mk_place_deref (rhs . into ()) , needs_unique) ; } } } Rvalue :: Ref (_ , _ , place) | Rvalue :: RawPtr (_ , place) => { let mut place = * place ; if place . projection . first () == Some (& PlaceElem :: Deref) && let Value :: Pointer (target , inner_needs_unique) = targets [place . local] && ! inner_needs_unique && can_perform_opt (target , location) { place = target . project_deeper (& place . projection [1 ..] , tcx) ; } assert_ne ! (place . local , local) ; if is_constant_place (place) { targets [local] = Value :: Pointer (place , needs_unique) ; } } _ => { } } } debug ! (? targets) ; let mut finder = ReplacementFinder { targets , can_perform_opt , allowed_replacements : FxHashSet :: default () } ; let reachable_blocks = traversal :: reachable_as_bitset (body) ; for (bb , bbdata) in body . basic_blocks . iter_enumerated () { if reachable_blocks . contains (bb) { finder . visit_basic_block_data (bb , bbdata) ; } } let allowed_replacements = finder . allowed_replacements ; return Replacer { tcx , targets : finder . targets , storage_to_remove , allowed_replacements , any_replacement : false , } ; struct ReplacementFinder < 'tcx , F > { targets : IndexVec < Local , Value < 'tcx > > , can_perform_opt : F , allowed_replacements : FxHashSet < (Local , Location) > , } impl < 'tcx , F > Visitor < 'tcx > for ReplacementFinder < 'tcx , F > where F : FnMut (Place < 'tcx > , Location) -> bool , { fn visit_place (& mut self , place : & Place < 'tcx > , ctxt : PlaceContext , loc : Location) { if matches ! (ctxt , PlaceContext :: NonUse (_)) { return ; } if place . projection . first () != Some (& PlaceElem :: Deref) { return ; } let mut place = place . as_ref () ; loop { if let Value :: Pointer (target , needs_unique) = self . targets [place . local] { let perform_opt = (self . can_perform_opt) (target , loc) ; debug ! (? place , ? target , ? needs_unique , ? perform_opt) ; if let & [PlaceElem :: Deref] = & target . projection [..] { assert ! (perform_opt) ; self . allowed_replacements . insert ((target . local , loc)) ; place . local = target . local ; continue ; } else if perform_opt { self . allowed_replacements . insert ((target . local , loc)) ; } else if needs_unique { self . targets [place . local] = Value :: Unknown ; } } break ; } } } } #[doc = " Compute the set of locals that can be fully replaced."] #[doc = ""] #[doc = " We consider a local to be replaceable iff it's only used in a `Deref` projection `*_local` or"] #[doc = " non-use position (like storage statements and debuginfo)."] fn fully_replaceable_locals (ssa : & SsaLocals) -> DenseBitSet < Local > { let mut replaceable = DenseBitSet :: new_empty (ssa . num_locals ()) ; for local in ssa . locals () { if ssa . num_direct_uses (local) == 0 { replaceable . insert (local) ; } } ssa . meet_copy_equivalence (& mut replaceable) ; replaceable } #[doc = " Utility to help performing substitution of `*pattern` by `target`."] struct Replacer < 'tcx > { tcx : TyCtxt < 'tcx > , targets : IndexVec < Local , Value < 'tcx > > , storage_to_remove : DenseBitSet < Local > , allowed_replacements : FxHashSet < (Local , Location) > , any_replacement : bool , } impl < 'tcx > MutVisitor < 'tcx > for Replacer < 'tcx > { fn tcx (& self) -> TyCtxt < 'tcx > { self . tcx } fn visit_var_debug_info (& mut self , debuginfo : & mut VarDebugInfo < 'tcx >) { while let VarDebugInfoContents :: Place (ref mut place) = debuginfo . value && place . projection . is_empty () && let Value :: Pointer (target , _) = self . targets [place . local] && target . projection . iter () . all (| p | p . can_use_in_debuginfo ()) { if let Some ((& PlaceElem :: Deref , rest)) = target . projection . split_last () { * place = Place :: from (target . local) . project_deeper (rest , self . tcx) ; self . any_replacement = true ; } else { break ; } } self . super_var_debug_info (debuginfo) ; } fn visit_place (& mut self , place : & mut Place < 'tcx > , ctxt : PlaceContext , loc : Location) { loop { if place . projection . first () != Some (& PlaceElem :: Deref) { return ; } let Value :: Pointer (target , _) = self . targets [place . local] else { return } ; let perform_opt = match ctxt { PlaceContext :: NonUse (NonUseContext :: VarDebugInfo) => { target . projection . iter () . all (| p | p . can_use_in_debuginfo ()) } PlaceContext :: NonUse (_) => true , _ => self . allowed_replacements . contains (& (target . local , loc)) , } ; if ! perform_opt { return ; } * place = target . project_deeper (& place . projection [1 ..] , self . tcx) ; self . any_replacement = true ; } } fn visit_statement (& mut self , stmt : & mut Statement < 'tcx > , loc : Location) { match stmt . kind { StatementKind :: StorageLive (l) | StatementKind :: StorageDead (l) if self . storage_to_remove . contains (l) => { stmt . make_nop () ; } _ => self . super_statement (stmt , loc) , } } }